/* === BEGIN tolerances-calc.js === */
/**
 * TOLERANCES & FITS CALCULATION ENGINE (ISO 286:1988, ANSI B4.1, ISO 2768-1)
 * Hệ Thống Tính Toán Cơ Khí Độc Lập - Client-Side 100% Offline
 * Chuẩn Zero-Tolerance (Δ = 0.000000) so với MITCalc 1.74
 */

(function (window) {
    'use strict';

    const db = window.TOLERANCES_DB;

    // Helper: Tìm vị trí bước kích thước trong mảng
    function getSizeIndex(size, steps) {
        for (let i = 0; i < steps.length; i++) {
            if (size <= steps[i]) {
                return i;
            }
        }
        return steps.length - 1;
    }

    /**
     * Tra cứu trị số dung sai tiêu chuẩn ISO 286 (IT01 đến IT18)
     * @param {number} D - Kích thước danh nghĩa (mm)
     * @param {number|string} itGrade - Cấp chính xác (01, 0, 1 ... 18)
     * @returns {number|null} Trị số dung sai IT tính bằng micromet (µm)
     */
    function getIT(D, itGrade) {
        if (!db || D <= 0 || D > 3150) return null;
        const key = String(itGrade).toUpperCase().startsWith('IT') ? String(itGrade).toUpperCase() : `IT${itGrade}`;
        if (!db.it_data || !db.it_data[key]) return null;
        const idx = getSizeIndex(D, db.it_steps);
        return db.it_data[key][idx];
    }

    /**
     * Tra cứu sai lệch giới hạn của Trục theo ISO 286 (a đến zc)
     * @param {number} D - Kích thước danh nghĩa (mm)
     * @param {string} letter - Ký hiệu miền dung sai trục ('a' đến 'zc')
     * @param {number} itGrade - Cấp chính xác (1 đến 18)
     * @returns {{es: number, ei: number, IT: number}|null} Sai lệch es, ei và IT (µm)
     */
    function getShaftDeviations(D, letter, itGrade) {
        if (!db || D <= 0 || D > 3150) return null;
        const IT = getIT(D, itGrade);
        if (IT === null) return null;

        const lowLetter = letter.toLowerCase();
        let colKey = lowLetter;

        // Xử lý các quy tắc phụ cho j và k
        if (lowLetter === 'j') {
            if (itGrade === 5) colKey = 'j_5.0';
            else if (itGrade === 6) colKey = 'j_6.0';
            else if (itGrade === 7 || itGrade === 8) colKey = 'j_7.0';
            else colKey = 'j_7.0';
        } else if (lowLetter === 'k') {
            if (itGrade <= 7) colKey = 'k_4~7';
            else colKey = 'k_8~';
        }

        // Trường hợp đặc biệt js: đối xứng qua đường không (Zero line)
        if (lowLetter === 'js') {
            const half = IT / 2.0;
            return {
                es: half,
                ei: -half,
                IT: IT
            };
        }

        if (!db.shaft_data || !db.shaft_data[colKey]) return null;
        const idx = getSizeIndex(D, db.shaft_steps);
        const val = db.shaft_data[colKey][idx];
        if (val === null || val === undefined) return null;

        let es, ei;
        // Các chữ cái a đến h: val là sai lệch trên es (es <= 0)
        if (['a', 'b', 'c', 'cd', 'd', 'e', 'ef', 'f', 'fg', 'g', 'h'].includes(lowLetter)) {
            es = val;
            ei = es - IT;
        } else if (lowLetter === 'j') {
            // Với j: val trong bảng là sai lệch dưới
            ei = val;
            es = ei + IT;
        } else {
            // Các chữ cái k đến zc: val là sai lệch dưới ei (ei >= 0)
            ei = val;
            es = ei + IT;
        }

        return { es, ei, IT };
    }

    /**
     * Tra cứu sai lệch giới hạn của Lỗ theo ISO 286 (A đến ZC)
     * @param {number} D - Kích thước danh nghĩa (mm)
     * @param {string} letter - Ký hiệu miền dung sai lỗ ('A' đến 'ZC')
     * @param {number} itGrade - Cấp chính xác (1 đến 18)
     * @returns {{ES: number, EI: number, IT: number}|null} Sai lệch ES, EI và IT (µm)
     */
    function getHoleDeviations(D, letter, itGrade) {
        if (!db || D <= 0 || D > 3150) return null;
        const IT = getIT(D, itGrade);
        if (IT === null) return null;

        const upLetter = letter.toUpperCase();
        let colKey = upLetter;

        // Xử lý các quy tắc phụ cho J và N
        if (upLetter === 'J') {
            if (itGrade === 6) colKey = 'J_6.0';
            else if (itGrade === 7) colKey = 'J_7.0';
            else if (itGrade === 8) colKey = 'J_8.0';
            else colKey = 'J_7.0';
        } else if (upLetter === 'N') {
            if (itGrade <= 8) colKey = 'N_~8';
            else colKey = 'N_9~';
        }

        // Trường hợp đặc biệt JS: đối xứng qua đường không
        if (upLetter === 'JS') {
            const half = IT / 2.0;
            return {
                ES: half,
                EI: -half,
                IT: IT
            };
        }

        if (!db.hole_data || !db.hole_data[colKey]) return null;
        const idx = getSizeIndex(D, db.hole_steps);
        const val = db.hole_data[colKey][idx];
        if (val === null || val === undefined) return null;

        // Lấy giá trị hiệu chỉnh Delta nếu có (K, M, N trong IT3-IT8, P-ZC trong IT7-IT8)
        let delta = 0.0;
        const strGrade = String(itGrade);
        if (db.delta_data && db.delta_data[strGrade]) {
            if (['K', 'M', 'N'].includes(upLetter) && itGrade >= 3 && itGrade <= 8) {
                delta = db.delta_data[strGrade][idx] || 0.0;
            } else if (['P', 'R', 'S', 'T', 'U', 'V', 'X', 'Y', 'Z', 'ZA', 'ZB', 'ZC'].includes(upLetter) && itGrade >= 7 && itGrade <= 8) {
                delta = db.delta_data[strGrade][idx] || 0.0;
            }
        }

        let ES, EI;
        // Các chữ cái A đến H: val là sai lệch dưới EI (EI >= 0)
        if (['A', 'B', 'C', 'CD', 'D', 'E', 'EF', 'F', 'FG', 'G', 'H'].includes(upLetter)) {
            EI = val;
            ES = EI + IT;
        } else if (upLetter === 'J') {
            ES = val;
            EI = ES - IT;
        } else {
            // Các chữ cái K đến ZC: val là sai lệch trên ES (ES <= 0) kèm hiệu chỉnh Delta
            ES = val + delta;
            EI = ES - IT;
        }

        return { ES, EI, IT };
    }

    /**
     * Tính toán toàn diện mối lắp ghép ISO 286
     * @param {number} D - Kích thước danh nghĩa (mm)
     * @param {string} holeLetter - Ký hiệu lỗ (ví dụ 'H')
     * @param {number} holeGrade - Cấp IT lỗ (ví dụ 7)
     * @param {string} shaftLetter - Ký hiệu trục (ví dụ 'g')
     * @param {number} shaftGrade - Cấp IT trục (ví dụ 6)
     */
    function calculateISOFit(D, holeLetter, holeGrade, shaftLetter, shaftGrade) {
        const hole = getHoleDeviations(D, holeLetter, holeGrade);
        const shaft = getShaftDeviations(D, shaftLetter, shaftGrade);

        if (!hole || !shaft) {
            return { error: 'Thông số ngoài phạm vi tiêu chuẩn ISO 286 (D > 3150mm hoặc miền dung sai không xác định)' };
        }

        const ES = hole.ES;
        const EI = hole.EI;
        const es = shaft.es;
        const ei = shaft.ei;

        // Kích thước giới hạn của Lỗ (mm)
        const D_max = D + ES / 1000.0;
        const D_min = D + EI / 1000.0;
        const T_D = (ES - EI) / 1000.0; // mm

        // Kích thước giới hạn của Trục (mm)
        const d_max = D + es / 1000.0;
        const d_min = D + ei / 1000.0;
        const T_d = (es - ei) / 1000.0; // mm

        // Tính các đại lượng khe hở / độ dôi (µm)
        // Khe hở: S = D - d. S_max = ES - ei, S_min = EI - es
        // Độ dôi: N = d - D = -S. N_max = es - EI, N_min = ei - ES
        const S_max = ES - ei;
        const S_min = EI - es;
        const N_max = es - EI;
        const N_min = ei - ES;

        // Phân loại bản chất mối ghép
        let fitType = 'Clearance'; // Lắp lỏng
        let fitTypeName = 'Lắp lỏng (Clearance)';
        if (EI >= es) {
            fitType = 'Clearance';
            fitTypeName = 'Lắp lỏng (Clearance)';
        } else if (ES <= ei) {
            fitType = 'Interference';
            fitTypeName = 'Lắp chặt (Interference)';
        } else {
            fitType = 'Transition';
            fitTypeName = 'Lắp trung gian (Transition)';
        }

        // Dung sai lắp ghép T_fit = T_D + T_d (µm)
        const T_fit = hole.IT + shaft.IT;

        return {
            D: D,
            hole: {
                symbol: `${holeLetter.toUpperCase()}${holeGrade}`,
                letter: holeLetter.toUpperCase(),
                grade: holeGrade,
                ES: ES, // µm
                EI: EI, // µm
                IT: hole.IT, // µm
                D_max: D_max, // mm
                D_min: D_min, // mm
                T_D: T_D // mm
            },
            shaft: {
                symbol: `${shaftLetter.toLowerCase()}${shaftGrade}`,
                letter: shaftLetter.toLowerCase(),
                grade: shaftGrade,
                es: es, // µm
                ei: ei, // µm
                IT: shaft.IT, // µm
                d_max: d_max, // mm
                d_min: d_min, // mm
                T_d: T_d // mm
            },
            fit: {
                name: `${holeLetter.toUpperCase()}${holeGrade}/${shaftLetter.toLowerCase()}${shaftGrade}`,
                type: fitType,
                typeName: fitTypeName,
                S_max: S_max, // µm
                S_min: S_min, // µm
                N_max: N_max, // µm
                N_min: N_min, // µm
                meanClearance: (S_max + S_min) / 2.0, // µm
                T_fit: T_fit, // µm
                // Quy đổi sang mm
                S_max_mm: S_max / 1000.0,
                S_min_mm: S_min / 1000.0,
                N_max_mm: N_max / 1000.0,
                N_min_mm: N_min / 1000.0,
                T_fit_mm: T_fit / 1000.0
            }
        };
    }

    /**
     * Tra cứu cấp dung sai ANSI B4.1 (Grade 4 đến 13)
     * @param {number} D_inch - Kích thước danh nghĩa tính bằng inch
     * @param {number} grade - Cấp chính xác ANSI (4 đến 13)
     * @returns {number|null} Trị số dung sai tính bằng 10^-3 inch (mils)
     */
    function getANSI_IT(D_inch, grade) {
        if (!db || D_inch <= 0 || D_inch > 200) return null;
        const key = String(grade);
        if (!db.ansi_it_data || !db.ansi_it_data[key]) return null;
        const idx = getSizeIndex(D_inch, db.ansi_it_steps);
        return db.ansi_it_data[key][idx];
    }

    /**
     * Tính toán mối lắp ghép ưu tiên ANSI B4.1
     * @param {number} D_inch - Kích thước danh nghĩa (inch)
     * @param {string} fitCategory - Phân loại: 'hole_rc', 'hole_lc', 'hole_lt', 'hole_ln', 'hole_fn' (hoặc shaft_)
     * @param {number} fitIndex - Chỉ số kiểu lắp (1 đến N)
     */
    function calculateANSIFit(D_inch, fitCategory, fitIndex) {
        if (!db || !db.ansi_pref_fits || !db.ansi_pref_fits[fitCategory]) {
            return { error: 'Không tìm thấy nhóm kiểu lắp ANSI chỉ định' };
        }
        const fitsList = db.ansi_pref_fits[fitCategory];
        if (fitIndex < 1 || fitIndex > fitsList.length) {
            return { error: 'Chỉ số kiểu lắp ANSI không hợp lệ' };
        }
        const fitDef = fitsList[fitIndex - 1];

        // Lấy tolerance của lỗ và trục
        const hGrade = fitDef.hole_it;
        const sGrade = fitDef.shaft_it;
        const holeTol = getANSI_IT(D_inch, hGrade);
        const shaftTol = getANSI_IT(D_inch, sGrade);

        if (holeTol === null || shaftTol === null) {
            return { error: 'Kích thước vượt quá giới hạn ANSI B4.1 (D > 200 in)' };
        }

        const isHoleBasis = fitCategory.startsWith('hole_');
        let ES = 0, EI = 0, es = 0, ei = 0;

        // Tìm cột sai lệch trục trong ansi_shaft_data
        let sLetter = fitDef.shaft_letter.toLowerCase();
        let colKey = sLetter;
        // Kiểm tra các cột có subgrade
        for (const k of db.ansi_shaft_cols) {
            if (k.startsWith(sLetter)) {
                // ví dụ d_8.0, d_9.0, g_4~5, g_6.0...
                if (k.includes(String(sGrade))) {
                    colKey = k;
                    break;
                } else if (k.includes('~') && sGrade >= parseInt(k.split('_')[1].split('~')[0]) && sGrade <= parseInt(k.split('_')[1].split('~')[1])) {
                    colKey = k;
                    break;
                }
            }
        }

        const idx = getSizeIndex(D_inch, db.ansi_shaft_steps);
        let sDev = (db.ansi_shaft_data[colKey] && db.ansi_shaft_data[colKey][idx] !== null) ? db.ansi_shaft_data[colKey][idx] : 0.0;

        if (isHoleBasis) {
            // Hệ Lỗ cơ bản: EI = 0, ES = +holeTol
            EI = 0.0;
            ES = holeTol;

            // Xử lý loại lắp:
            if (sLetter === 'js') {
                es = shaftTol / 2.0;
                ei = -shaftTol / 2.0;
            } else if (fitCategory.includes('rc') || fitCategory.includes('lc')) {
                // Lắp lỏng: sDev là sai lệch trên es
                es = sDev;
                ei = es - shaftTol;
            } else if (fitCategory.includes('ln') || fitCategory.includes('fn')) {
                // Lắp chặt: sDev là sai lệch dưới ei
                ei = sDev;
                es = ei + shaftTol;
            } else {
                // LT Transition: nếu là k, m, n thì sDev là sai lệch dưới ei
                if (['k', 'm', 'n'].includes(sLetter)) {
                    ei = sDev;
                    es = ei + shaftTol;
                } else {
                    es = sDev;
                    ei = es - shaftTol;
                }
            }
        } else {
            // Hệ Trục cơ bản: es = 0, ei = -shaftTol
            es = 0.0;
            ei = -shaftTol;

            if (fitCategory.includes('rc') || fitCategory.includes('lc')) {
                EI = -sDev;
                ES = EI + holeTol;
            } else if (fitCategory.includes('ln') || fitCategory.includes('fn')) {
                ES = -sDev;
                EI = ES - holeTol;
            } else {
                EI = -sDev;
                ES = EI + holeTol;
            }
        }

        // Khe hở lớn nhất / nhỏ nhất (10^-3 in)
        const S_max = ES - ei;
        const S_min = EI - es;
        const N_max = es - EI;
        const N_min = ei - ES;

        return {
            D_inch: D_inch,
            D_mm: D_inch * 25.4,
            fitName: fitDef.fit,
            holeDesc: fitDef.hole_desc,
            shaftDesc: fitDef.shaft_desc,
            hole: {
                symbol: fitDef.hole_desc || `H${hGrade}`,
                ES: ES, // 10^-3 in
                EI: EI, // 10^-3 in
                tol: holeTol,
                ES_um: ES * 25.4,
                EI_um: EI * 25.4
            },
            shaft: {
                symbol: fitDef.shaft_desc || `${sLetter}${sGrade}`,
                es: es, // 10^-3 in
                ei: ei, // 10^-3 in
                tol: shaftTol,
                es_um: es * 25.4,
                ei_um: ei * 25.4
            },
            clearance: {
                max_inch: S_max / 1000.0,
                min_inch: S_min / 1000.0,
                max_mils: S_max,
                min_mils: S_min,
                max_um: S_max * 25.4,
                min_um: S_min * 25.4
            }
        };
    }

    /**
     * Tra cứu dung sai chung ISO 2768-1
     * @param {string} type - 'linear', 'broken_edges', 'angular'
     * @param {number} value - Kích thước (mm)
     * @param {string} tolClass - 'f', 'm', 'c', 'v'
     * @returns {string|number|null} Sai lệch giới hạn (± mm hoặc ± độ/phút)
     */
    function lookupISO2768(type, value, tolClass) {
        if (!db || !db.iso2768 || !db.iso2768[type]) return null;
        const tObj = db.iso2768[type];
        const cls = tolClass.toLowerCase();
        if (!tObj[cls]) return null;

        const steps = tObj.steps;
        let idx = steps.length - 1;
        for (let i = 0; i < steps.length; i++) {
            if (value <= steps[i]) {
                idx = i;
                break;
            }
        }

        const res = tObj[cls][idx];
        return res !== null ? res : '—';
    }

    /**
     * Tự động thiết kế kiểu lắp ghép theo khe hở / độ dôi yêu cầu (Fit Design Engine)
     * @param {number} D - Kích thước danh nghĩa (mm)
     * @param {number} system - 1: Hệ Lỗ (Hole basis), 2: Hệ Trục (Shaft basis)
     * @param {number} fitType - 1: Lắp lỏng, 2: Lắp trung gian, 3: Lắp chặt
     * @param {number} desiredMax - Khe hở lớn nhất (hoặc Độ dôi nhỏ nhất) mong muốn (µm)
     * @param {number} desiredMin - Khe hở nhỏ nhất (hoặc Độ dôi lớn nhất) mong muốn (µm)
     * @returns {Array} Top 15 kiểu lắp ghép tối ưu nhất
     */
    function designFits(D, system, fitType, desiredMax, desiredMin) {
        if (!db || D <= 0 || D > 3150) return [];

        const candidates = [];
        const isHoleBasis = (system === 1);

        // Danh sách các cấp IT thông dụng cho thiết kế (IT4 đến IT11)
        const itGrades = [4, 5, 6, 7, 8, 9, 10, 11];

        // Tập hợp chữ cái phù hợp theo loại lắp ghép
        let testLetters = [];
        if (fitType === 1) {
            // Lắp lỏng: shaft a đến h (hoặc hole A đến H)
            testLetters = isHoleBasis 
                ? ['c', 'd', 'e', 'f', 'g', 'h']
                : ['C', 'D', 'E', 'F', 'G', 'H'];
        } else if (fitType === 2) {
            // Lắp trung gian: shaft js, j, k, m, n
            testLetters = isHoleBasis 
                ? ['js', 'j', 'k', 'm', 'n']
                : ['JS', 'J', 'K', 'M', 'N'];
        } else {
            // Lắp chặt: shaft p, r, s, t, u, v, x
            testLetters = isHoleBasis 
                ? ['p', 'r', 's', 't', 'u', 'v', 'x']
                : ['P', 'R', 'S', 'T', 'U', 'V', 'X'];
        }

        // Quét các tổ hợp (Hole IT x Shaft Letter x Shaft IT)
        for (const hGrade of itGrades) {
            for (const sLetter of testLetters) {
                for (const sGrade of itGrades) {
                    // Chênh lệch cấp IT giữa lỗ và trục thông thường không quá 2 cấp
                    if (Math.abs(hGrade - sGrade) > 2) continue;

                    let fitRes;
                    if (isHoleBasis) {
                        fitRes = calculateISOFit(D, 'H', hGrade, sLetter, sGrade);
                    } else {
                        fitRes = calculateISOFit(D, sLetter, hGrade, 'h', sGrade);
                    }

                    if (!fitRes || fitRes.error) continue;

                    // Kiểm tra đúng bản chất mối ghép
                    if (fitType === 1 && fitRes.fit.type !== 'Clearance') continue;
                    if (fitType === 2 && fitRes.fit.type !== 'Transition') continue;
                    if (fitType === 3 && fitRes.fit.type !== 'Interference') continue;

                    let curMax, curMin;
                    if (fitType === 1) {
                        curMax = fitRes.fit.S_max;
                        curMin = fitRes.fit.S_min;
                    } else if (fitType === 3) {
                        curMax = fitRes.fit.N_max;
                        curMin = fitRes.fit.N_min;
                    } else {
                        curMax = fitRes.fit.S_max;
                        curMin = fitRes.fit.N_max;
                    }

                    // Tính hàm mục tiêu sai số bình phương tương đối
                    const errMax = (desiredMax !== 0) ? Math.abs(curMax - desiredMax) / Math.abs(desiredMax) : Math.abs(curMax - desiredMax);
                    const errMin = (desiredMin !== 0) ? Math.abs(curMin - desiredMin) / Math.abs(desiredMin) : Math.abs(curMin - desiredMin);

                    // Phạt nhẹ các cấp IT quá thô (> IT8)
                    const penalty = (hGrade > 8 ? (hGrade - 8) * 0.1 : 0) + (sGrade > 8 ? (sGrade - 8) * 0.1 : 0);
                    const score = Math.sqrt(errMax * errMax + errMin * errMin) + penalty;

                    candidates.push({
                        fitName: fitRes.fit.name,
                        holeSymbol: fitRes.hole.symbol,
                        shaftSymbol: fitRes.shaft.symbol,
                        ES: fitRes.hole.ES,
                        EI: fitRes.hole.EI,
                        es: fitRes.shaft.es,
                        ei: fitRes.shaft.ei,
                        curMax: curMax,
                        curMin: curMin,
                        score: score,
                        isPreferred: (hGrade <= 8 && sGrade <= 8 && ['f', 'g', 'h', 'k', 'n', 'p', 's'].includes(sLetter.toLowerCase()))
                    });
                }
            }
        }

        // Sắp xếp theo score tăng dần (điểm thấp nhất = khớp nhất)
        candidates.sort((a, b) => a.score - b.score);

        // Lấy Top 15
        return candidates.slice(0, 15);
    }

    // Export module ra window
    window.TolerancesEngine = {
        getIT,
        getShaftDeviations,
        getHoleDeviations,
        calculateISOFit,
        calculateANSIFit,
        getANSI_IT,
        lookupISO2768,
        designFits,
        getSizeIndex
    };

})(typeof window !== 'undefined' ? window : this);

/* === END tolerances-calc.js === */

/* === BEGIN tolerances-canvas.js === */
/**
 * TOLERANCES & FITS 2D CANVAS VISUALIZER
 * Biểu đồ Miền Dung Sai & Mối Lắp Ghép (Tolerance Zones Diagram)
 * Đồ họa động thời gian thực chuẩn 2D CAD
 */

(function (window) {
    'use strict';

    class TolerancesVisualizer {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            if (!this.canvas) return;
            this.ctx = this.canvas.getContext('2d');

            // Virtual resolution
            this.vWidth = 1200;
            this.vHeight = 650;

            // Pan & Zoom state
            this.scale = 1.0;
            this.offsetX = 0;
            this.offsetY = 0;

            // Current fit data
            this.fitData = null;

            // Touch & Drag state
            this.isDragging = false;
            this.dragStartX = 0;
            this.dragStartY = 0;
            this.initialPinchDistance = null;

            this.initEvents();
        }

        initEvents() {
            if (!this.canvas) return;

            // Mouse pan
            this.canvas.addEventListener('mousedown', (e) => {
                this.isDragging = true;
                this.dragStartX = e.clientX;
                this.dragStartY = e.clientY;
            });

            window.addEventListener('mousemove', (e) => {
                if (!this.isDragging) return;
                const dx = e.clientX - this.dragStartX;
                const dy = e.clientY - this.dragStartY;
                this.offsetX += dx;
                this.offsetY += dy;
                this.dragStartX = e.clientX;
                this.dragStartY = e.clientY;
                this.render();
            });

            window.addEventListener('mouseup', () => {
                this.isDragging = false;
            });

            // Wheel zoom
            this.canvas.addEventListener('wheel', (e) => {
                e.preventDefault();
                const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
                this.scale = Math.max(0.3, Math.min(5.0, this.scale * zoomFactor));
                this.render();
            }, { passive: false });

            // Touch events (Mobile multi-touch engine)
            this.canvas.addEventListener('touchstart', (e) => {
                if (e.touches.length === 1) {
                    this.isDragging = true;
                    this.dragStartX = e.touches[0].clientX;
                    this.dragStartY = e.touches[0].clientY;
                } else if (e.touches.length === 2) {
                    this.isDragging = false;
                    const dx = e.touches[0].clientX - e.touches[1].clientX;
                    const dy = e.touches[0].clientY - e.touches[1].clientY;
                    this.initialPinchDistance = Math.hypot(dx, dy);
                }
            }, { passive: true });

            this.canvas.addEventListener('touchmove', (e) => {
                if (e.touches.length === 1 && this.isDragging) {
                    const dx = e.touches[0].clientX - this.dragStartX;
                    const dy = e.touches[0].clientY - this.dragStartY;
                    this.offsetX += dx;
                    this.offsetY += dy;
                    this.dragStartX = e.touches[0].clientX;
                    this.dragStartY = e.touches[0].clientY;
                    this.render();
                } else if (e.touches.length === 2 && this.initialPinchDistance) {
                    const dx = e.touches[0].clientX - e.touches[1].clientX;
                    const dy = e.touches[0].clientY - e.touches[1].clientY;
                    const currentDist = Math.hypot(dx, dy);
                    const factor = currentDist / this.initialPinchDistance;
                    this.scale = Math.max(0.3, Math.min(5.0, this.scale * factor));
                    this.initialPinchDistance = currentDist;
                    this.render();
                }
            }, { passive: true });

            this.canvas.addEventListener('touchend', () => {
                this.isDragging = false;
                this.initialPinchDistance = null;
            });
        }

        resetView() {
            this.scale = 1.0;
            this.offsetX = 0;
            this.offsetY = 0;
            this.render();
        }

        zoomIn() {
            this.scale = Math.min(5.0, this.scale * 1.25);
            this.render();
        }

        zoomOut() {
            this.scale = Math.max(0.3, this.scale / 1.25);
            this.render();
        }

        downloadPNG() {
            if (!this.canvas) return;
            const link = document.createElement('a');
            const fitName = this.fitData && this.fitData.fit ? this.fitData.fit.name.replace('/', '_') : 'Fit';
            link.download = `Bieu_do_dung_sai_${fitName}.png`;
            link.href = this.canvas.toDataURL('image/png');
            link.click();
        }

        updateData(fitData) {
            this.fitData = fitData;
            this.render();
        }

        render() {
            if (!this.canvas || !this.ctx) return;
            const ctx = this.ctx;

            // Clear background
            ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

            // Background Grid (Engineering dark theme)
            ctx.fillStyle = '#0b1329';
            ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

            if (!this.fitData || !this.fitData.hole || !this.fitData.shaft) {
                ctx.fillStyle = '#64748b';
                ctx.font = '16px Segoe UI, sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText('Chưa có dữ liệu mối lắp ghép', this.canvas.width / 2, this.canvas.height / 2);
                return;
            }

            const w = this.canvas.width;
            const h = this.canvas.height;

            const ES = this.fitData.hole.ES;
            const EI = this.fitData.hole.EI;
            const es = this.fitData.shaft.es;
            const ei = this.fitData.shaft.ei;

            // Max span in µm
            const maxVal = Math.max(ES, EI, es, ei, 0);
            const minVal = Math.min(ES, EI, es, ei, 0);
            const totalSpan = Math.max(40, maxVal - minVal);

            // Auto-scale vertical pixels per µm
            const availableHeight = h * 0.55 * this.scale;
            const pxPerUm = availableHeight / totalSpan;

            // Zero Line Y
            const zeroY = h / 2 + this.offsetY + ((maxVal + minVal) / 2) * pxPerUm;

            ctx.save();

            // 1. Draw Background coordinate grid
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            for (let x = 0; x < w; x += 40) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, h);
                ctx.stroke();
            }
            for (let y = 0; y < h; y += 40) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(w, y);
                ctx.stroke();
            }

            // 2. Draw Zero Line (Đường không 0)
            ctx.strokeStyle = '#38bdf8';
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.moveTo(60, zeroY);
            ctx.lineTo(w - 60, zeroY);
            ctx.stroke();

            // Label Zero Line
            ctx.fillStyle = '#38bdf8';
            ctx.font = 'bold 12px Segoe UI, sans-serif';
            ctx.textAlign = 'left';
            ctx.fillText('Đường 0', 70, zeroY - 6);
            ctx.fillText(`Kích thước danh nghĩa d = D = ${this.fitData.D} mm`, w - 380, zeroY - 8);

            // 3. Ruler Ticks on the left
            ctx.strokeStyle = '#475569';
            ctx.fillStyle = '#94a3b8';
            ctx.font = '11px Segoe UI, sans-serif';
            ctx.textAlign = 'right';

            const niceStep = totalSpan > 200 ? 50 : (totalSpan > 80 ? 20 : 10);
            const startTick = Math.floor(minVal / niceStep) * niceStep;
            const endTick = Math.ceil(maxVal / niceStep) * niceStep;

            for (let val = startTick; val <= endTick; val += niceStep) {
                const y = zeroY - val * pxPerUm;
                if (y >= 40 && y <= h - 40) {
                    ctx.beginPath();
                    ctx.moveTo(110, y);
                    ctx.lineTo(130, y);
                    ctx.stroke();
                    if (val !== 0) {
                        ctx.fillText(`${val > 0 ? '+' : ''}${val} µm`, 105, y + 4);
                    }
                }
            }

            // Vertical axis line
            ctx.beginPath();
            ctx.moveTo(130, 40);
            ctx.lineTo(130, h - 40);
            ctx.stroke();

            // 4. Draw Hole Tolerance Zone (Lỗ - Cyan)
            const holeX = w * 0.35 + this.offsetX;
            const blockWidth = 140 * this.scale;

            const holeTopY = zeroY - ES * pxPerUm;
            const holeBottomY = zeroY - EI * pxPerUm;
            const holeHeight = holeBottomY - holeTopY;

            // Fill Hole Block
            ctx.fillStyle = 'rgba(6, 182, 212, 0.25)';
            ctx.strokeStyle = '#06b6d4';
            ctx.lineWidth = 2;
            ctx.fillRect(holeX, holeTopY, blockWidth, holeHeight);
            ctx.strokeRect(holeX, holeTopY, blockWidth, holeHeight);

            // Hole Hatching Lines (45 deg)
            ctx.save();
            ctx.beginPath();
            ctx.rect(holeX, holeTopY, blockWidth, holeHeight);
            ctx.clip();
            ctx.strokeStyle = 'rgba(6, 182, 212, 0.35)';
            ctx.lineWidth = 1;
            for (let x = holeX - holeHeight; x < holeX + blockWidth + holeHeight; x += 12) {
                ctx.beginPath();
                ctx.moveTo(x, holeBottomY);
                ctx.lineTo(x + holeHeight, holeTopY);
                ctx.stroke();
            }
            ctx.restore();

            // Hole Labels
            ctx.fillStyle = '#22d3ee';
            ctx.font = 'bold 18px Segoe UI, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(`LỖ ${this.fitData.hole.symbol}`, holeX + blockWidth / 2, holeTopY + holeHeight / 2 + 6);

            // ES label
            ctx.font = 'bold 12px Segoe UI, sans-serif';
            ctx.fillStyle = '#67e8f9';
            ctx.textAlign = 'right';
            ctx.fillText(`ES = ${ES > 0 ? '+' : ''}${ES} µm`, holeX - 10, holeTopY + 4);
            ctx.beginPath();
            ctx.moveTo(holeX - 6, holeTopY);
            ctx.lineTo(holeX, holeTopY);
            ctx.stroke();

            // EI label
            ctx.fillText(`EI = ${EI > 0 ? '+' : ''}${EI} µm`, holeX - 10, holeBottomY + 4);
            ctx.beginPath();
            ctx.moveTo(holeX - 6, holeBottomY);
            ctx.lineTo(holeX, holeBottomY);
            ctx.stroke();

            // 5. Draw Shaft Tolerance Zone (Trục - Amber/Orange)
            const shaftX = w * 0.55 + this.offsetX;
            const shaftTopY = zeroY - es * pxPerUm;
            const shaftBottomY = zeroY - ei * pxPerUm;
            const shaftHeight = shaftBottomY - shaftTopY;

            // Fill Shaft Block
            ctx.fillStyle = 'rgba(245, 158, 11, 0.25)';
            ctx.strokeStyle = '#f59e0b';
            ctx.lineWidth = 2;
            ctx.fillRect(shaftX, shaftTopY, blockWidth, shaftHeight);
            ctx.strokeRect(shaftX, shaftTopY, blockWidth, shaftHeight);

            // Shaft Hatching Lines (-45 deg)
            ctx.save();
            ctx.beginPath();
            ctx.rect(shaftX, shaftTopY, blockWidth, shaftHeight);
            ctx.clip();
            ctx.strokeStyle = 'rgba(245, 158, 11, 0.35)';
            ctx.lineWidth = 1;
            for (let x = shaftX - shaftHeight; x < shaftX + blockWidth + shaftHeight; x += 12) {
                ctx.beginPath();
                ctx.moveTo(x, shaftTopY);
                ctx.lineTo(x + shaftHeight, shaftBottomY);
                ctx.stroke();
            }
            ctx.restore();

            // Shaft Labels
            ctx.fillStyle = '#fbbf24';
            ctx.font = 'bold 18px Segoe UI, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(`TRỤC ${this.fitData.shaft.symbol}`, shaftX + blockWidth / 2, shaftTopY + shaftHeight / 2 + 6);

            // es label
            ctx.font = 'bold 12px Segoe UI, sans-serif';
            ctx.fillStyle = '#fde68a';
            ctx.textAlign = 'left';
            ctx.fillText(`es = ${es > 0 ? '+' : ''}${es} µm`, shaftX + blockWidth + 10, shaftTopY + 4);
            ctx.beginPath();
            ctx.moveTo(shaftX + blockWidth, shaftTopY);
            ctx.lineTo(shaftX + blockWidth + 6, shaftTopY);
            ctx.stroke();

            // ei label
            ctx.fillText(`ei = ${ei > 0 ? '+' : ''}${ei} µm`, shaftX + blockWidth + 10, shaftBottomY + 4);
            ctx.beginPath();
            ctx.moveTo(shaftX + blockWidth, shaftBottomY);
            ctx.lineTo(shaftX + blockWidth + 6, shaftBottomY);
            ctx.stroke();

            // 6. Draw Fit Dimensions (Arrows for S_max, S_min or N_max, N_min)
            const fit = this.fitData.fit;
            const arrow1X = shaftX + blockWidth + 105;
            const arrow2X = shaftX + blockWidth + 195;

            if (fit.type === 'Clearance') {
                // S_max = ES - ei
                this.drawDimArrow(ctx, arrow1X, holeTopY, shaftBottomY, `S_max = ${fit.S_max} µm`, '#34d399');
                // S_min = EI - es
                this.drawDimArrow(ctx, arrow2X, holeBottomY, shaftTopY, `S_min = ${fit.S_min} µm`, '#38bdf8');
            } else if (fit.type === 'Interference') {
                // N_max = es - EI
                this.drawDimArrow(ctx, arrow1X, shaftTopY, holeBottomY, `N_max = ${fit.N_max} µm`, '#f87171');
                // N_min = ei - ES
                this.drawDimArrow(ctx, arrow2X, shaftBottomY, holeTopY, `N_min = ${fit.N_min} µm`, '#fbbf24');
            } else {
                // Transition: S_max and N_max
                this.drawDimArrow(ctx, arrow1X, holeTopY, shaftBottomY, `S_max = ${fit.S_max} µm`, '#34d399');
                this.drawDimArrow(ctx, arrow2X, shaftTopY, holeBottomY, `N_max = ${fit.N_max} µm`, '#f87171');
            }

            // Header info box
            ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
            ctx.strokeStyle = '#334155';
            ctx.fillRect(w - 290, 20, 270, 110);
            ctx.strokeRect(w - 290, 20, 270, 110);

            ctx.fillStyle = '#38bdf8';
            ctx.font = 'bold 15px Segoe UI, sans-serif';
            ctx.textAlign = 'left';
            ctx.fillText(`Mối ghép: ${fit.name}`, w - 275, 45);

            ctx.font = '13px Segoe UI, sans-serif';
            ctx.fillStyle = fit.type === 'Clearance' ? '#34d399' : (fit.type === 'Interference' ? '#f87171' : '#fbbf24');
            ctx.fillText(`Bản chất: ${fit.typeName}`, w - 275, 68);

            ctx.fillStyle = '#cbd5e1';
            if (fit.type === 'Clearance') {
                ctx.fillText(`S_max = ${fit.S_max} µm (${fit.S_max_mm} mm)`, w - 275, 90);
                ctx.fillText(`S_min = ${fit.S_min} µm (${fit.S_min_mm} mm)`, w - 275, 110);
            } else if (fit.type === 'Interference') {
                ctx.fillText(`N_max = ${fit.N_max} µm (${fit.N_max_mm} mm)`, w - 275, 90);
                ctx.fillText(`N_min = ${fit.N_min} µm (${fit.N_min_mm} mm)`, w - 275, 110);
            } else {
                ctx.fillText(`S_max = ${fit.S_max} µm | N_max = ${fit.N_max} µm`, w - 275, 90);
                ctx.fillText(`Dung sai ghép T_fit = ${fit.T_fit} µm`, w - 275, 110);
            }

            ctx.restore();
        }

        drawDimArrow(ctx, x, y1, y2, text, color) {
            if (Math.abs(y1 - y2) < 2) return;
            const topY = Math.min(y1, y2);
            const bottomY = Math.max(y1, y2);

            ctx.save();
            ctx.strokeStyle = color;
            ctx.fillStyle = color;
            ctx.lineWidth = 1.5;

            // Leader lines
            ctx.setLineDash([3, 3]);
            ctx.beginPath();
            ctx.moveTo(x - 20, topY);
            ctx.lineTo(x + 5, topY);
            ctx.moveTo(x - 20, bottomY);
            ctx.lineTo(x + 5, bottomY);
            ctx.stroke();
            ctx.setLineDash([]);

            // Main vertical line
            ctx.beginPath();
            ctx.moveTo(x, topY);
            ctx.lineTo(x, bottomY);
            ctx.stroke();

            // Arrows
            ctx.beginPath();
            ctx.moveTo(x, topY);
            ctx.lineTo(x - 4, topY + 8);
            ctx.lineTo(x + 4, topY + 8);
            ctx.closePath();
            ctx.fill();

            ctx.beginPath();
            ctx.moveTo(x, bottomY);
            ctx.lineTo(x - 4, bottomY - 8);
            ctx.lineTo(x + 4, bottomY - 8);
            ctx.closePath();
            ctx.fill();

            // Label
            ctx.font = 'bold 11px Segoe UI, sans-serif';
            ctx.textAlign = 'left';
            ctx.fillText(text, x + 8, (topY + bottomY) / 2 + 4);
            ctx.restore();
        }
    }

    window.TolerancesVisualizer = TolerancesVisualizer;

})(typeof window !== 'undefined' ? window : this);

/* === END tolerances-canvas.js === */

/* === BEGIN tolerances-ui.js === */
/**
 * TOLERANCES & FITS UI CONTROLLER
 * Xử lý tương tác giao diện người dùng, đồng bộ tính toán thời gian thực
 */

(function (window) {
    'use strict';

    let visualizer = null;
    let currentISOResult = null;

    function init() {
        // Khởi tạo visualizer
        visualizer = new window.TolerancesVisualizer('toleranceCanvas');

        initTabs();
        initAccordions();
        initISOControls();
        initANSIControls();
        initISO2768Controls();
        initFitDesignControls();
        initSurfaceFinishTable();

        // Tính toán ban đầu
        calculateAll();
    }

    // 1. Unified Toolbar & Canvas Controls
    function initTabs() {
        // Global accordion buttons
        const btnExpandAll = document.getElementById('btnExpandAll');
        const btnCollapseAll = document.getElementById('btnCollapseAll');
        if (btnExpandAll) {
            btnExpandAll.addEventListener('click', () => {
                document.querySelectorAll('.calc-section').forEach(s => s.classList.remove('collapsed'));
            });
        }
        if (btnCollapseAll) {
            btnCollapseAll.addEventListener('click', () => {
                document.querySelectorAll('.calc-section').forEach(s => s.classList.add('collapsed'));
            });
        }

        // Canvas controls
        const btnResetView = document.getElementById('btnResetCanvas');
        if (btnResetView) {
            btnResetView.addEventListener('click', () => {
                if (visualizer) visualizer.resetView();
            });
        }

        const btnZoomIn = document.getElementById('btnZoomInCanvas');
        if (btnZoomIn) {
            btnZoomIn.addEventListener('click', () => {
                if (visualizer) visualizer.zoomIn();
            });
        }

        const btnZoomOut = document.getElementById('btnZoomOutCanvas');
        if (btnZoomOut) {
            btnZoomOut.addEventListener('click', () => {
                if (visualizer) visualizer.zoomOut();
            });
        }

        const btnDownload = document.getElementById('btnDownloadCanvas');
        if (btnDownload) {
            btnDownload.addEventListener('click', () => {
                if (visualizer) visualizer.downloadPNG();
            });
        }

        const btnCopy = document.getElementById('btnCopyFitData');
        if (btnCopy) {
            btnCopy.addEventListener('click', copyFitDataToClipboard);
        }
    }

    // 2. Accordion Control
    function initAccordions() {
        document.querySelectorAll('.section-header').forEach(header => {
            header.addEventListener('click', () => {
                const section = header.closest('.calc-section');
                if (section) {
                    section.classList.toggle('collapsed');
                }
            });
        });
    }

    // 3. ISO 286 Controls
    function initISOControls() {
        const inpSize = document.getElementById('iso_nominal_size');
        const selSystem = document.getElementById('iso_system');
        const selType = document.getElementById('iso_type');
        const selPrefFit = document.getElementById('iso_preferred_fit');
        const selHoleLetter = document.getElementById('iso_hole_letter');
        const selHoleIT = document.getElementById('iso_hole_it');
        const selShaftLetter = document.getElementById('iso_shaft_letter');
        const selShaftIT = document.getElementById('iso_shaft_it');

        // Populate preferred fits list based on System & Type
        function updatePrefFitsList() {
            if (!selPrefFit || !window.TOLERANCES_DB) return;
            const system = selSystem ? parseInt(selSystem.value) : 1; // 1: Hole, 2: Shaft
            const type = selType ? parseInt(selType.value) : 1; // 1: Clear, 2: Trans, 3: Interf

            let listKey = '';
            if (system === 1) {
                listKey = type === 1 ? 'hole_clearance' : (type === 2 ? 'hole_transition' : 'hole_interference');
            } else {
                listKey = type === 1 ? 'shaft_clearance' : (type === 2 ? 'shaft_transition' : 'shaft_interference');
            }

            const fits = window.TOLERANCES_DB.pref_fits[listKey] || [];
            selPrefFit.innerHTML = '';

            fits.forEach((item, idx) => {
                const opt = document.createElement('option');
                opt.value = idx;
                opt.textContent = `${item.name}${item.pref === 1 ? ' ★ (Ưu tiên)' : ''}`;
                selPrefFit.appendChild(opt);
            });

            // Chọn kiểu mặc định
            if (fits.length > 0) {
                // Ưu tiên chọn H7/g6 hoặc H8/f7 nếu có
                let defIdx = 0;
                fits.forEach((f, i) => {
                    if (f.name === 'H7/g6' || f.name === 'H8/f7' || f.name === 'H7/h6') defIdx = i;
                });
                selPrefFit.selectedIndex = defIdx;
                applyPrefFit(fits[defIdx]);
            }
        }

        function applyPrefFit(fitObj) {
            if (!fitObj) return;
            const holeLetterName = window.TOLERANCES_DB.hole_list[fitObj.hole_letter - 1]?.letter || 'H';
            const shaftLetterName = window.TOLERANCES_DB.shaft_list[fitObj.shaft_letter - 1]?.letter || 'h';

            if (selHoleLetter) selHoleLetter.value = holeLetterName;
            if (selHoleIT) selHoleIT.value = fitObj.hole_it;
            if (selShaftLetter) selShaftLetter.value = shaftLetterName;
            if (selShaftIT) selShaftIT.value = fitObj.shaft_it;

            calculateISO();
        }

        if (selSystem) selSystem.addEventListener('change', updatePrefFitsList);
        if (selType) selType.addEventListener('change', updatePrefFitsList);

        if (selPrefFit) {
            selPrefFit.addEventListener('change', () => {
                const system = parseInt(selSystem.value);
                const type = parseInt(selType.value);
                const listKey = (system === 1) 
                    ? (type === 1 ? 'hole_clearance' : (type === 2 ? 'hole_transition' : 'hole_interference'))
                    : (type === 1 ? 'shaft_clearance' : (type === 2 ? 'shaft_transition' : 'shaft_interference'));
                const fits = window.TOLERANCES_DB.pref_fits[listKey] || [];
                const selected = fits[parseInt(selPrefFit.value)];
                applyPrefFit(selected);
            });
        }

        // Custom inputs
        [inpSize, selHoleLetter, selHoleIT, selShaftLetter, selShaftIT].forEach(el => {
            if (el) {
                el.addEventListener('input', calculateISO);
                el.addEventListener('change', calculateISO);
            }
        });

        // Khởi tạo danh sách preferred fits
        updatePrefFitsList();
    }

    // Tính toán ISO 286
    function calculateISO() {
        const inpSize = document.getElementById('iso_nominal_size');
        const selHoleLetter = document.getElementById('iso_hole_letter');
        const selHoleIT = document.getElementById('iso_hole_it');
        const selShaftLetter = document.getElementById('iso_shaft_letter');
        const selShaftIT = document.getElementById('iso_shaft_it');

        if (!inpSize || !selHoleLetter || !selHoleIT || !selShaftLetter || !selShaftIT) return;

        const D = parseFloat(inpSize.value.replace(',', '.')) || 50;
        const hLetter = selHoleLetter.value;
        const hGrade = parseInt(selHoleIT.value);
        const sLetter = selShaftLetter.value;
        const sGrade = parseInt(selShaftIT.value);

        const res = window.TolerancesEngine.calculateISOFit(D, hLetter, hGrade, sLetter, sGrade);
        if (!res || res.error) {
            console.warn(res ? res.error : 'Lỗi tính toán ISO');
            return;
        }

        currentISOResult = res;

        // Render DOM Results
        setVal('res_iso_fit_name', res.fit.name);
        setVal('res_iso_fit_type', res.fit.typeName);
        setVal('res_iso_hole_sym', res.hole.symbol);
        setVal('res_iso_hole_es', formatSigned(res.hole.ES));
        setVal('res_iso_hole_ei', formatSigned(res.hole.EI));
        setVal('res_iso_hole_it', res.hole.IT);
        setVal('res_iso_hole_dmax', res.hole.D_max.toFixed(4));
        setVal('res_iso_hole_dmin', res.hole.D_min.toFixed(4));
        setVal('res_iso_hole_td', res.hole.T_D.toFixed(4));

        setVal('res_iso_shaft_sym', res.shaft.symbol);
        setVal('res_iso_shaft_es', formatSigned(res.shaft.es));
        setVal('res_iso_shaft_ei', formatSigned(res.shaft.ei));
        setVal('res_iso_shaft_it', res.shaft.IT);
        setVal('res_iso_shaft_dmax', res.shaft.d_max.toFixed(4));
        setVal('res_iso_shaft_dmin', res.shaft.d_min.toFixed(4));
        setVal('res_iso_shaft_td', res.shaft.T_d.toFixed(4));

        // Fit clearances / interferences
        if (res.fit.type === 'Clearance') {
            setVal('lbl_iso_clearance_max', 'Khe hở lớn nhất (S_max):');
            setVal('res_iso_clearance_max', `${res.fit.S_max} µm (${res.fit.S_max_mm.toFixed(4)} mm)`);
            setVal('lbl_iso_clearance_min', 'Khe hở nhỏ nhất (S_min):');
            setVal('res_iso_clearance_min', `${res.fit.S_min} µm (${res.fit.S_min_mm.toFixed(4)} mm)`);
        } else if (res.fit.type === 'Interference') {
            setVal('lbl_iso_clearance_max', 'Độ dôi lớn nhất (N_max):');
            setVal('res_iso_clearance_max', `${res.fit.N_max} µm (${res.fit.N_max_mm.toFixed(4)} mm)`);
            setVal('lbl_iso_clearance_min', 'Độ dôi nhỏ nhất (N_min):');
            setVal('res_iso_clearance_min', `${res.fit.N_min} µm (${res.fit.N_min_mm.toFixed(4)} mm)`);
        } else {
            setVal('lbl_iso_clearance_max', 'Khe hở lớn nhất (S_max):');
            setVal('res_iso_clearance_max', `${res.fit.S_max} µm (${res.fit.S_max_mm.toFixed(4)} mm)`);
            setVal('lbl_iso_clearance_min', 'Độ dôi lớn nhất (N_max):');
            setVal('res_iso_clearance_min', `${res.fit.N_max} µm (${res.fit.N_max_mm.toFixed(4)} mm)`);
        }

        setVal('res_iso_mean_allowance', `${res.fit.meanClearance.toFixed(1)} µm`);
        setVal('res_iso_tfit', `${res.fit.T_fit} µm (${res.fit.T_fit_mm.toFixed(4)} mm)`);

        // Badge type color
        const badge = document.getElementById('badge_iso_fit_type');
        if (badge) {
            badge.className = 'badge-type ' + (res.fit.type === 'Clearance' ? 'badge-clearance' : (res.fit.type === 'Interference' ? 'badge-interference' : 'badge-transition'));
            badge.textContent = res.fit.typeName;
        }

        // Cập nhật biểu đồ Canvas 2D
        if (visualizer) {
            visualizer.updateData(res);
        }

        // Cập nhật highlight phương pháp gia công khả thi (Mục 5.0)
        updateSurfaceFinishHighlights(hGrade, sGrade);
    }

    // 4. ANSI B4.1 Controls
    function initANSIControls() {
        const inpSizeInch = document.getElementById('ansi_nominal_size');
        const selSystem = document.getElementById('ansi_system');
        const selType = document.getElementById('ansi_type');
        const selPrefFit = document.getElementById('ansi_preferred_fit');

        function updateANSIPrefList() {
            if (!selPrefFit || !window.TOLERANCES_DB) return;
            const system = selSystem ? parseInt(selSystem.value) : 1; // 1: Hole, 2: Shaft
            const type = selType ? selType.value : 'rc'; // rc, lc, lt, ln, fn
            const key = (system === 1 ? 'hole_' : 'shaft_') + type;

            const fits = window.TOLERANCES_DB.ansi_pref_fits[key] || [];
            selPrefFit.innerHTML = '';

            fits.forEach((item, idx) => {
                const opt = document.createElement('option');
                opt.value = idx + 1;
                opt.textContent = `${item.fit} (${item.hole_desc}/${item.shaft_desc})`;
                selPrefFit.appendChild(opt);
            });

            if (fits.length > 0) {
                selPrefFit.selectedIndex = 0;
                calculateANSI();
            }
        }

        if (selSystem) selSystem.addEventListener('change', updateANSIPrefList);
        if (selType) selType.addEventListener('change', updateANSIPrefList);
        if (selPrefFit) selPrefFit.addEventListener('change', calculateANSI);
        if (inpSizeInch) {
            inpSizeInch.addEventListener('input', calculateANSI);
            inpSizeInch.addEventListener('change', calculateANSI);
        }

        updateANSIPrefList();
    }

    function calculateANSI() {
        const inpSizeInch = document.getElementById('ansi_nominal_size');
        const selSystem = document.getElementById('ansi_system');
        const selType = document.getElementById('ansi_type');
        const selPrefFit = document.getElementById('ansi_preferred_fit');

        if (!inpSizeInch || !selSystem || !selType || !selPrefFit) return;

        const D_inch = parseFloat(inpSizeInch.value.replace(',', '.')) || 2.0;
        const system = parseInt(selSystem.value);
        const type = selType.value;
        const fitIdx = parseInt(selPrefFit.value);
        const key = (system === 1 ? 'hole_' : 'shaft_') + type;

        const res = window.TolerancesEngine.calculateANSIFit(D_inch, key, fitIdx);
        if (!res || res.error) {
            console.warn(res ? res.error : 'Lỗi tính toán ANSI');
            return;
        }

        setVal('res_ansi_fit_name', res.fitName);
        setVal('res_ansi_size_mm', `${res.D_mm.toFixed(3)} mm`);

        setVal('res_ansi_hole_sym', res.hole.symbol);
        setVal('res_ansi_hole_es', `${formatSigned(res.hole.ES)} mil (${formatSigned(res.hole.ES_um.toFixed(1))} µm)`);
        setVal('res_ansi_hole_ei', `${formatSigned(res.hole.EI)} mil (${formatSigned(res.hole.EI_um.toFixed(1))} µm)`);
        setVal('res_ansi_hole_tol', `${res.hole.tol} mil`);

        setVal('res_ansi_shaft_sym', res.shaft.symbol);
        setVal('res_ansi_shaft_es', `${formatSigned(res.shaft.es)} mil (${formatSigned(res.shaft.es_um.toFixed(1))} µm)`);
        setVal('res_ansi_shaft_ei', `${formatSigned(res.shaft.ei)} mil (${formatSigned(res.shaft.ei_um.toFixed(1))} µm)`);
        setVal('res_ansi_shaft_tol', `${res.shaft.tol} mil`);

        setVal('res_ansi_clearance_max', `${res.clearance.max_mils.toFixed(1)} mil (${res.clearance.max_inch.toFixed(4)} in / ${res.clearance.max_um.toFixed(1)} µm)`);
        setVal('res_ansi_clearance_min', `${res.clearance.min_mils.toFixed(1)} mil (${res.clearance.min_inch.toFixed(4)} in / ${res.clearance.min_um.toFixed(1)} µm)`);
    }

    // 5. ISO 2768-1 Controls
    function initISO2768Controls() {
        const inpLinear = document.getElementById('iso2768_linear_val');
        const selLinearCls = document.getElementById('iso2768_linear_class');
        const inpRadius = document.getElementById('iso2768_radius_val');
        const selRadiusCls = document.getElementById('iso2768_radius_class');
        const inpAngle = document.getElementById('iso2768_angle_val');
        const selAngleCls = document.getElementById('iso2768_angle_class');

        function updateISO2768() {
            if (inpLinear && selLinearCls) {
                const val = parseFloat(inpLinear.value.replace(',', '.')) || 10;
                const cls = selLinearCls.value;
                const dev = window.TolerancesEngine.lookupISO2768('linear', val, cls);
                setVal('res_iso2768_linear_dev', typeof dev === 'number' ? `± ${dev} mm` : dev);
            }
            if (inpRadius && selRadiusCls) {
                const val = parseFloat(inpRadius.value.replace(',', '.')) || 2;
                const cls = selRadiusCls.value;
                const dev = window.TolerancesEngine.lookupISO2768('broken_edges', val, cls);
                setVal('res_iso2768_radius_dev', typeof dev === 'number' ? `± ${dev} mm` : dev);
            }
            if (inpAngle && selAngleCls) {
                const val = parseFloat(inpAngle.value.replace(',', '.')) || 25;
                const cls = selAngleCls.value;
                const dev = window.TolerancesEngine.lookupISO2768('angular', val, cls);
                setVal('res_iso2768_angle_dev', dev);
            }
        }

        [inpLinear, selLinearCls, inpRadius, selRadiusCls, inpAngle, selAngleCls].forEach(el => {
            if (el) {
                el.addEventListener('input', updateISO2768);
                el.addEventListener('change', updateISO2768);
            }
        });

        updateISO2768();
    }

    // 6. Fit Design Controls (Mục 4.0)
    function initFitDesignControls() {
        const btnDesign = document.getElementById('btnStartFitDesign');
        const inpSize = document.getElementById('dsgn_size');
        const selSystem = document.getElementById('dsgn_system');
        const selType = document.getElementById('dsgn_type');
        const inpMax = document.getElementById('dsgn_desired_max');
        const inpMin = document.getElementById('dsgn_desired_min');
        const tbody = document.getElementById('dsgn_results_tbody');

        if (!btnDesign || !tbody) return;

        btnDesign.addEventListener('click', () => {
            const D = parseFloat(inpSize.value.replace(',', '.')) || 50;
            const system = parseInt(selSystem.value) || 1;
            const fitType = parseInt(selType.value) || 1;
            const desiredMax = parseFloat(inpMax.value.replace(',', '.')) || 50;
            const desiredMin = parseFloat(inpMin.value.replace(',', '.')) || 10;

            const results = window.TolerancesEngine.designFits(D, system, fitType, desiredMax, desiredMin);

            tbody.innerHTML = '';
            if (results.length === 0) {
                tbody.innerHTML = '<tr><td colspan="7" style="color:#ef4444; text-align:center;">Không tìm thấy kiểu lắp nào thỏa mãn điều kiện yêu cầu</td></tr>';
                return;
            }

            results.forEach((c, i) => {
                const tr = document.createElement('tr');
                if (c.isPreferred) tr.className = 'design-row-pref';

                tr.innerHTML = `
                    <td><b>${i + 1}</b></td>
                    <td><span style="color:#38bdf8; font-weight:700;">${c.fitName}</span> ${c.isPreferred ? '★' : ''}</td>
                    <td>${c.holeSymbol} [${formatSigned(c.ES)}, ${formatSigned(c.EI)}]</td>
                    <td>${c.shaftSymbol} [${formatSigned(c.es)}, ${formatSigned(c.ei)}]</td>
                    <td><b style="color:#34d399;">${c.curMax} µm</b></td>
                    <td><b style="color:#fbbf24;">${c.curMin} µm</b></td>
                    <td><button class="design-btn-apply" data-fit="${c.fitName}" data-d="${D}">Áp dụng</button></td>
                `;
                tbody.appendChild(tr);
            });

            // Gán sự kiện click nút áp dụng
            tbody.querySelectorAll('.design-btn-apply').forEach(btn => {
                btn.addEventListener('click', () => {
                    const fitStr = btn.dataset.fit;
                    const parts = fitStr.split('/');
                    if (parts.length === 2) {
                        const hPart = parts[0];
                        const sPart = parts[1];
                        const hLetter = hPart.replace(/[0-9]/g, '');
                        const hIT = hPart.replace(/[^0-9]/g, '');
                        const sLetter = sPart.replace(/[0-9]/g, '');
                        const sIT = sPart.replace(/[^0-9]/g, '');

                        const elSize = document.getElementById('iso_nominal_size');
                        const elHL = document.getElementById('iso_hole_letter');
                        const elHIT = document.getElementById('iso_hole_it');
                        const elSL = document.getElementById('iso_shaft_letter');
                        const elSIT = document.getElementById('iso_shaft_it');

                        if (elSize) elSize.value = btn.dataset.d;
                        if (elHL) elHL.value = hLetter;
                        if (elHIT) elHIT.value = hIT;
                        if (elSL) elSL.value = sLetter;
                        if (elSIT) elSIT.value = sIT;

                        calculateISO();

                        // Cuộn mượt mà đến biểu đồ Canvas để xem trực quan
                        const canvasContainer = document.getElementById('toleranceCanvasContainer');
                        if (canvasContainer) {
                            canvasContainer.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        }
                    }
                });
            });
        });
    }

    // 7. Surface Finish Matrix (Mục 5.0)
    function initSurfaceFinishTable() {
        const tbody = document.getElementById('surface_processes_tbody');
        if (!tbody || !window.TOLERANCES_DB || !window.TOLERANCES_DB.processes) return;

        tbody.innerHTML = '';
        window.TOLERANCES_DB.processes.forEach((proc, idx) => {
            const tr = document.createElement('tr');
            tr.dataset.grades = JSON.stringify(proc.grades || []);

            // Thanh ma trận IT2 đến IT16
            let barHtml = '';
            for (let g = 2; g <= 16; g++) {
                if (proc.grades && proc.grades.includes(g)) {
                    barHtml += `<span class="it-cell-active" data-grade="${g}" title="${proc.name}: IT${g}">IT${g}</span>`;
                } else {
                    barHtml += `<span class="it-cell-inactive" data-grade="${g}">·</span>`;
                }
            }

            tr.innerHTML = `
                <td style="text-align:center; color:#94a3b8; font-weight:600;">${idx + 1}</td>
                <td>
                    <div style="font-weight:700; color:#f8fafc; font-size:0.92rem;">${proc.name_vi || proc.name}</div>
                    <div style="font-size:0.78rem; color:#64748b;">${proc.name}</div>
                </td>
                <td style="color:#38bdf8; font-weight:700; white-space:nowrap;">IT${proc.min_grade} ~ IT${proc.max_grade}</td>
                <td style="color:#34d399; font-weight:600; white-space:nowrap;">${proc.ra_min} ~ ${proc.ra_max} µm</td>
                <td>
                    <div class="it-bar-container">${barHtml}</div>
                </td>
            `;
            tbody.appendChild(tr);
        });
    }

    // Dynamic highlight cho Section 5.0 khi chọn Lỗ / Trục ở Mục 1.0
    function updateSurfaceFinishHighlights(holeIT, shaftIT) {
        const tbody = document.getElementById('surface_processes_tbody');
        if (!tbody) return;

        tbody.querySelectorAll('tr').forEach(tr => {
            try {
                const grades = JSON.parse(tr.dataset.grades || '[]');
                const canMakeHole = grades.includes(holeIT);
                const canMakeShaft = grades.includes(shaftIT);

                if (canMakeHole && canMakeShaft) {
                    tr.className = 'row-proc-feasible';
                } else {
                    tr.className = '';
                }

                // Highlight active IT cells
                tr.querySelectorAll('.it-cell-active').forEach(cell => {
                    const g = parseInt(cell.dataset.grade);
                    if (g === holeIT || g === shaftIT) {
                        cell.classList.add('it-cell-highlight');
                    } else {
                        cell.classList.remove('it-cell-highlight');
                    }
                });
            } catch (e) {}
        });
    }

    // Sao chép thông số kỹ thuật mối lắp ghép vào Clipboard
    function copyFitDataToClipboard() {
        if (!currentISOResult) return;
        const res = currentISOResult;
        const D = res.D;
        const fit = res.fit;
        const hole = res.hole;
        const shaft = res.shaft;

        let clearInfo = '';
        if (fit.type === 'Clearance') {
            clearInfo = `  + Khe hở lớn nhất (S_max): ${fit.S_max} µm (${fit.S_max_mm.toFixed(4)} mm)\n  + Khe hở nhỏ nhất (S_min): ${fit.S_min} µm (${fit.S_min_mm.toFixed(4)} mm)`;
        } else if (fit.type === 'Interference') {
            clearInfo = `  + Độ dôi lớn nhất (N_max): ${fit.N_max} µm (${fit.N_max_mm.toFixed(4)} mm)\n  + Độ dôi nhỏ nhất (N_min): ${fit.N_min} µm (${fit.N_min_mm.toFixed(4)} mm)`;
        } else {
            clearInfo = `  + Khe hở lớn nhất (S_max): ${fit.S_max} µm (${fit.S_max_mm.toFixed(4)} mm)\n  + Độ dôi lớn nhất (N_max): ${fit.N_max} µm (${fit.N_max_mm.toFixed(4)} mm)`;
        }

        const text = 
`======================================================================
KẾT QUẢ TÍNH TOÁN DUNG SAI & LẮP GHÉP THEO ISO 286:1988
- Kích thước danh nghĩa: D = ${D} mm
- Kiểu lắp ghép: ${fit.name} (${fit.typeName})
----------------------------------------------------------------------
1. CHI TIẾT LỖ (HOLE): ${hole.symbol}
   - Sai lệch trên ES: ${formatSigned(hole.ES)} µm
   - Sai lệch dưới EI: ${formatSigned(hole.EI)} µm
   - Dung sai lỗ T_D: ${hole.IT} µm (${hole.T_D.toFixed(4)} mm)
   - Kích thước giới hạn: D_max = ${hole.D_max.toFixed(4)} mm, D_min = ${hole.D_min.toFixed(4)} mm

2. CHI TIẾT TRỤC (SHAFT): ${shaft.symbol}
   - Sai lệch trên es: ${formatSigned(shaft.es)} µm
   - Sai lệch dưới ei: ${formatSigned(shaft.ei)} µm
   - Dung sai trục T_d: ${shaft.IT} µm (${shaft.T_d.toFixed(4)} mm)
   - Kích thước giới hạn: d_max = ${shaft.d_max.toFixed(4)} mm, d_min = ${shaft.d_min.toFixed(4)} mm

3. ĐẶC TÍNH MỐI GHÉP:
${clearInfo}
   - Độ hở/dôi trung bình: ${fit.meanClearance.toFixed(1)} µm
   - Dung sai ghép tổng (T_fit): ${fit.T_fit} µm (${fit.T_fit_mm.toFixed(4)} mm)
======================================================================`;

        navigator.clipboard.writeText(text).then(() => {
            const btn = document.getElementById('btnCopyFitData');
            if (btn) {
                const oldText = btn.textContent;
                btn.textContent = 'Đã Sao Chép! ✓';
                btn.style.background = '#059669';
                setTimeout(() => {
                    btn.textContent = oldText;
                    btn.style.background = '#10b981';
                }, 2000);
            }
        }).catch(() => {
            alert('Không thể truy cập Clipboard trình duyệt.');
        });
    }

    function calculateAll() {
        calculateISO();
        calculateANSI();
    }

    function setVal(id, text) {
        const el = document.getElementById(id);
        if (el) el.textContent = text;
    }

    function formatSigned(num) {
        if (typeof num !== 'number') return num;
        return num > 0 ? `+${num}` : `${num}`;
    }

    // Chạy khi trang tải xong
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

})(typeof window !== 'undefined' ? window : this);

/* === END tolerances-ui.js === */

